(7409963, 1167577, 124815, '<td valign="top">Coming straight from the hair saloon! Good frontal view</td>', 'Coming straight from the hair saloon! Good frontal view', '2015-10-14 16:06:28.000000', NULL, 1),
(7409964, 1167673, 124815, '<td valign="top">A touch less sharpening would really benefit this image. I played with the cropping and I would trim 1/3 from the right. What do you think? The monolithic shape might be sort of an Ayn Rand type of picture</td>', 'A touch less sharpening would really benefit this image. I played with the cropping and I would trim 1/3 from the right. What do you think? The monolithic shape might be sort of an Ayn Rand type of picture', '2015-10-14 16:10:06.000000', NULL, 1),
(7409966, 1167660, 124815, '<td valign="top">Ah, too much sharpening again! And I do like the gaps in the power lines, the fall into the cloud blanket.</td>', 'Ah, too much sharpening again! And I do like the gaps in the power lines, the fall into the cloud blanket.', '2015-10-14 16:15:16.000000', NULL, 1),
(7409967, 1167585, 124815, '<td valign="top">I like the lego-land quality of this composition. To include the word "power" just to make it fit the challenge does not help this eerie image. I do get the illusory meaning.<br/>bump</td>', 'I like the lego-land quality of this composition. To include the word "power" just to make it fit the challenge does not help this eerie image. I do get the illusory meaning.bump', '2015-10-14 16:16:31.000000', NULL, 1),
